#!/usr/bin/env node
/**
 * How much code the source generators write for an example, next to the code written by hand.
 *
 * ⚠️ `obj/…/generated/` is never emptied — not by an incremental build, not by `--no-incremental`, not
 * by the gate's clean build into `artifacts/`. A file a generator stops writing stays there, so
 * counting that folder counts types renamed days ago: it can give TimeOff.Leave 379 files where the
 * generator wrote 364. So each project is rebuilt on its own here, with its generated files
 * written to a folder emptied first: every file counted is one the generator wrote on this run.
 *
 *   1. `dotnet build` of the example's solution, incremental: every reference is current.
 *   2. For each project, `-t:Rebuild -p:BuildProjectReferences=false` with
 *      `CompilerGeneratedFilesOutputPath` pointing at `artifacts/generated-code-stats/generated/<Project>`.
 *   3. Every line is classified by `lib/csharp-lines.mjs`: code, comment, directive, blank. The header
 *      of a generated file — the banner from `// <auto-generated/>` to `#nullable enable` — is left out
 *      of every count and reported on its own. Hand-written files are counted whole.
 *
 * Hand-written means the `.cs` files under the project folder, outside `bin/` and `obj/`; `.razor`,
 * JSON and the rest are not counted.
 *
 *   node scripts/generated-code-stats.mjs                  → time-off and showcase
 *   node scripts/generated-code-stats.mjs showcase         → the examples named (folders under examples/)
 *   node scripts/generated-code-stats.mjs --skip-build     → re-read the generated files of the last run
 *
 * The report is printed, and written in full — every file with its counts — to
 * `artifacts/generated-code-stats/report.json`.
 */
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { addMeasures, emptyMeasure, measureSource } from './lib/csharp-lines.mjs';

// The same reason as in check.mjs: MSBuild nodes left alive accumulate across runs.
process.env.MSBUILDDISABLENODEREUSE = '1';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(REPO, 'artifacts', 'generated-code-stats');
const GENERATED = join(OUT, 'generated');
// The folder Roslyn names after the generator's type; the only generator whose hint names carry a kind.
const UNIFIED_GENERATOR = 'Pragmatic.SourceGenerator.PragmaticSourceGenerator';

const args = process.argv.slice(2);
const skipBuild = args.includes('--skip-build');
const examples = args.filter(a => !a.startsWith('--'));
if (examples.length === 0) examples.push('time-off', 'showcase');

const report = { measuredAt: new Date().toISOString(), examples: [] };

for (const example of examples) {
  const solution = solutionOf(example);
  const projects = projectsOf(solution);

  if (!skipBuild) {
    console.log(`building ${relative(REPO, solution)} …`);
    dotnet(['build', solution, '-v:q', '-nologo', '-clp:ErrorsOnly']);
    for (const project of projects) {
      const out = join(GENERATED, project.name);
      rmSync(out, { recursive: true, force: true });
      console.log(`  generating ${project.name} …`);
      dotnet(['build', project.path, '-t:Rebuild', '-p:BuildProjectReferences=false',
        '-p:EmitCompilerGeneratedFiles=true', `-p:CompilerGeneratedFilesOutputPath=${out}`,
        '-v:q', '-nologo', '-clp:ErrorsOnly']);
    }
  }

  report.examples.push({ name: example, projects: projects.map(measureProject) });
}

mkdirSync(OUT, { recursive: true });
writeFileSync(join(OUT, 'report.json'), JSON.stringify(report, null, 2));

for (const example of report.examples) print(example);
console.log(`\nfull report: ${relative(REPO, join(OUT, 'report.json'))}`);

// ─── measuring ────────────────────────────────────────────────────────────────

function measureProject(project) {
  const handFiles = sourcesUnder(project.dir, { skip: ['bin', 'obj'] });
  const hand = handFiles.reduce((m, f) => addMeasures(m, measureSource(readFileSync(f, 'utf8'))), emptyMeasure());

  const generators = [];
  const out = join(GENERATED, project.name);
  // Roslyn writes <output>/<generator assembly>/<generator type>/<hint name>; no folder, nothing generated.
  for (const assembly of existsSync(out) ? readdirSync(out) : []) {
    for (const type of readdirSync(join(out, assembly))) {
      const files = sourcesUnder(join(out, assembly, type)).map(f => ({
        hint: basename(f),
        kind: type === UNIFIED_GENERATOR ? artifactKind(basename(f)) : null,
        ...measureSource(readFileSync(f, 'utf8'), { header: true }),
      }));
      generators.push({
        assembly,
        type,
        pragmatic: assembly.startsWith('Pragmatic.'),
        total: files.reduce((m, f) => addMeasures(m, pick(f)), emptyMeasure()),
        files,
      });
    }
  }

  return {
    name: project.name,
    path: relative(REPO, project.path).replaceAll('\\', '/'),
    role: project.role,
    handWritten: hand,
    generators,
  };
}

/**
 * What a file of the unified generator is, from its hint name (`VirtualFolderHints`): a module's names
 * are type-first (`{Namespace}.{Type}.{Artifact}`), so the artifact is the last segment; a host's are
 * function-first (`EntityConfig.{…}`, `DbContext.{…}`, `Endpoint.{…}`, `Host.{…}`), so it is the first;
 * `_Infra.{Category}.…` and `_Metadata.{Category}.…` are named by their category. `_Boundary.{Boundary}.{Part}`
 * and `_Specification.{…}.{Artifact}` drop the name in the middle, so a boundary's interface is one kind
 * whichever boundary it is — the kinds of two examples compare.
 *
 * The standalone generators (client, mocks, contract tests) name their files after the type they
 * write; they are reported whole, per project, and have no kind.
 */
function artifactKind(hint) {
  const segments = hint.replace(/\.g\.cs$|\.cs$/, '').split('.');
  if (segments[0] === '_Boundary' || segments[0] === '_Specification') return `${segments[0]}.${segments.at(-1)}`;
  if (segments[0].startsWith('_')) return segments.slice(0, 2).join('.');
  if (['EntityConfig', 'DbContext', 'Endpoint', 'Host'].includes(segments[0])) return segments[0];
  return segments.at(-1);
}

function pick(m) {
  const { hint, kind, ...counts } = m;
  return counts;
}

// ─── printing ─────────────────────────────────────────────────────────────────

function print(example) {
  console.log(`\n== ${example.name}`);
  header();

  // By role of the project the code lands in: a mock or a contract test generated into a test project is
  // not an answer to "how much does the module get for what was written in src".
  const byRole = () => ({ src: emptyMeasure(), tests: emptyMeasure() });
  const hand = byRole();
  const pragmatic = byRole();
  const other = byRole();
  const unified = emptyMeasure();
  const kinds = new Map();

  for (const project of example.projects) {
    console.log(`  ${project.name}${project.role === 'tests' ? ' (tests)' : ''}`);
    row('    written by hand', project.handWritten);
    addMeasures(hand[project.role], project.handWritten);

    for (const generator of project.generators) {
      // The folder is the generator's full type name; its assembly already says whose it is.
      const name = generator.type.split('.').at(-1);
      row(`    ${generator.pragmatic ? 'generated · ' : 'generated (other) · '}${name}`, generator.total);
      addMeasures((generator.pragmatic ? pragmatic : other)[project.role], generator.total);
      if (generator.type !== UNIFIED_GENERATOR) continue;
      addMeasures(unified, generator.total);
      for (const file of generator.files) {
        const k = kinds.get(file.kind) ?? emptyMeasure();
        kinds.set(file.kind, addMeasures(k, pick(file)));
      }
    }
  }

  console.log(`  ${example.name}, in total`);
  row('    written by hand — src', hand.src);
  row('    generated by Pragmatic — into src', pragmatic.src);
  row('    generated by other generators — into src', other.src);
  row('    written by hand — tests', hand.tests);
  row('    generated by Pragmatic — into tests', pragmatic.tests);
  row('    generated by other generators — into tests', other.tests);
  const generated = [pragmatic.src, pragmatic.tests, other.src, other.tests];
  const headerLines = generated.reduce((n, m) => n + m.headerLines, 0);
  const headerChars = generated.reduce((n, m) => n + m.headerChars, 0);
  console.log(`    generated-file headers left out: ${fmt(headerLines)} lines, ${fmt(headerChars)} characters`);
  if (hand.src.code > 0)
    console.log(`    Pragmatic-generated code per hand-written line, in src: ${(pragmatic.src.code / hand.src.code).toFixed(1)}×`);

  if (kinds.size === 0) return;
  const ranked = [...kinds].sort((a, b) => b[1].code - a[1].code);
  console.log(`\n  what PragmaticSourceGenerator wrote for ${example.name}, by artifact (share of its code)`);
  header();
  for (const [kind, m] of ranked.slice(0, 15)) row(`    ${kind}`, m, unified.code);
  const rest = ranked.slice(15).reduce((m, [, k]) => addMeasures(m, k), emptyMeasure());
  if (rest.files > 0) row(`    ${ranked.length - 15} other artifacts`, rest, unified.code);
}

function header() {
  console.log(`  ${''.padEnd(52)}${['files', 'lines', 'code', 'comment', 'chars'].map(h => h.padStart(10)).join('')}`);
}

function row(label, m, share) {
  const cells = [m.files, m.lines, m.code, m.comment, m.chars].map(n => fmt(n).padStart(10)).join('');
  const pct = share ? `${(100 * m.code / share).toFixed(1).padStart(7)}%` : '';
  console.log(`  ${label.padEnd(52).slice(0, 52)}${cells}${pct}`);
}

function fmt(n) {
  return n.toLocaleString('en-US');
}

// ─── the example's projects ───────────────────────────────────────────────────

function solutionOf(example) {
  const dir = join(REPO, 'examples', example);
  const solutions = existsSync(dir) ? readdirSync(dir).filter(f => f.endsWith('.slnx')) : [];
  if (solutions.length !== 1)
    fail(`examples/${example}: expected one .slnx, found ${solutions.length}`);
  return join(dir, solutions[0]);
}

/** The projects the solution lists inside the example folder: src and tests, not the framework's. */
function projectsOf(solution) {
  const text = readFileSync(solution, 'utf8');
  const paths = [...text.matchAll(/<Project\s+Path="([^"]+)"/g)].map(m => m[1]).filter(p => !p.startsWith('..'));
  return paths.map(p => {
    const path = join(dirname(solution), p);
    return {
      name: basename(path, '.csproj'),
      path,
      dir: dirname(path),
      role: p.replaceAll('\\', '/').startsWith('tests/') ? 'tests' : 'src',
    };
  });
}

function sourcesUnder(dir, { skip = [] } = {}) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap(e => {
    const full = join(dir, e.name);
    if (e.isDirectory()) return skip.includes(e.name) ? [] : sourcesUnder(full, { skip });
    return e.name.endsWith('.cs') ? [full] : [];
  });
}

function dotnet(commandArgs) {
  const result = spawnSync('dotnet', commandArgs, { cwd: REPO, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 });
  if (result.status !== 0)
    fail(`dotnet ${commandArgs.slice(0, 2).join(' ')} failed (exit ${result.status}):\n${(result.stdout + result.stderr).trim().slice(-4000)}`);
}

function fail(message) {
  console.error(`FAIL ${message}`);
  process.exit(1);
}
